import{_ as a,o as d,c as e,ag as l}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Claude 桌面版体验","description":"AI Agent 零基础教程","frontmatter":{"title":"Claude 桌面版体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/05-claude.md","filePath":"guide/05-claude.md","lastUpdated":null}'),i={name:"guide/05-claude.md"};function r(o,t,h,n,u,c){return d(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="claude-桌面版体验" tabindex="-1">Claude 桌面版体验 <a class="header-anchor" href="#claude-桌面版体验" aria-label="Permalink to &quot;Claude 桌面版体验&quot;">​</a></h1><blockquote><p>状态：正文完成；账号受限，完整测试阻塞</p><p>本机版本：1.22209.3.0</p><p>最后本机核对：2026-08-12；订阅核验：2026-08-11</p><p>本文性质：Claude 在本教程中作为「实际使用前先检查账号与地区可用性」的真实阻断案例，不提供性能数据，不推导普遍封号率，不提供绕过限制的方法。</p></blockquote><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p>综合能力值得关注，但对中国大陆新手，<strong>账号与地区稳定性必须先于功能和价格判断</strong>。作者账号在本教程写作期间已被封，桌面端只能核对登录前欢迎页，因此当前不能把 Claude 作为无条件首选，也不能凭印象评价其桌面任务体验。</p><h2 id="_2-测试版本和地区" tabindex="-1">2. 测试版本和地区 <a class="header-anchor" href="#_2-测试版本和地区" aria-label="Permalink to &quot;2. 测试版本和地区&quot;">​</a></h2><ul><li>测试日期：2026-08-12（本机界面核对）；订阅信息核验 2026-08-11</li><li>正式产品名称与测试入口：Claude for Windows（WindowsApps 安装包名为 <code>Claude</code>）</li><li>地区版本：国际版（Anthropic 官方）；无中国版独立产品线</li><li>具体产品线：Desktop</li><li>账号区域与计费币种：未公开作者账号区域；订阅以美元计价</li><li>当前账号状态：<strong>受限/被封</strong>（作者亲历，原因未核实）</li><li>官方服务是否覆盖当前地区：需读者自行核对官方地区支持</li><li>注册、登录与支付前提：需可用的账号注册渠道与支付方式</li><li>账号受限后的申诉与恢复入口：官方支持渠道；作者申诉结果待记录</li><li>桌面客户端版本：1.22209.3.0</li><li>操作系统：Windows</li><li>官方下载来源：Anthropic 官网（Windows/macOS 桌面安装包）</li><li>入门分组：海外闭源托管型综合 Agent</li><li>主要任务方向：工作 / 内容 / 设计 / 代码（官方定位，本轮未实测）</li><li>开放与后台运行方式：云端</li><li>自主程度：中—高（官方宣传，本轮未实测）</li><li>建议基础：零基础可用（前提：账号稳定）</li><li>使用方案：Free / Pro / Max</li><li>官方订阅名称、价格与周期：Free $0；Pro 年付 $200（折合 $17/月）或月付 $20；Max 从 $100/月起（可选相对 Pro 的 5 倍或 20 倍用量）</li><li>套餐内用量单位：按用量窗口（未核实到公开 Credits 等价物）</li><li>用量重置时间与结转规则：见官方订阅页，未核验</li><li>官方 API 是否另行计费：是，按 Token 单独计费</li><li>是否支持 BYOK：官方桌面端不适用；第三方切换工具（如 CC Switch）改变的是模型通道，不等同官方订阅体验</li><li>免费额度及核验来源：Free 档 $0；未核实到面向所有个人学生的通用折扣（官方 Education 方案面向高校机构）</li><li>新用户或学生福利：无公开可引用的个人学生福利</li><li>最后核验日期：2026-08-11</li><li>测试者背景：作者，本教程写作期间账号被封</li></ul><h2 id="_3-下载、安装与首次启动" tabindex="-1">3. 下载、安装与首次启动 <a class="header-anchor" href="#_3-下载、安装与首次启动" aria-label="Permalink to &quot;3. 下载、安装与首次启动&quot;">​</a></h2><ul><li>下载和安装：本机为 WindowsApps 安装，安装流程正常；</li><li>登录：因账号被封，只能停留在登录前欢迎页，无法进入主工作区；</li><li>首次权限提示：未验证（未登录）；</li><li>主界面导航：欢迎页极简——大面积白色留白、中央橙色标志、<code>Claude for Windows</code> 标题、底部黑色 <code>Get started</code> 按钮；</li><li>新手从启动到完成第一个任务：待可用账号复测；</li><li>是否有只能通过 CLI/TUI 完成的重要能力：官方提供 Claude Code（CLI），与桌面端为不同入口；本轮均未实测。</li></ul><h2 id="_4-免费额度、订阅与计费" tabindex="-1">4. 免费额度、订阅与计费 <a class="header-anchor" href="#_4-免费额度、订阅与计费" aria-label="Permalink to &quot;4. 免费额度、订阅与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实际记录</th><th>官方来源</th><th>最后核验日期</th></tr></thead><tbody><tr><td>免费额度</td><td>Free $0；未核实到所有个人学生通用折扣</td><td>Claude Pricing</td><td>2026-08-11</td></tr><tr><td>官方订阅</td><td>Pro 年付 $200 / 月付 $20；Max $100/月起</td><td>Claude Pricing</td><td>2026-08-11</td></tr><tr><td>用量单位与重置规则</td><td>Pro 含 Claude Code、Cowork、Design、Science；API 计费另算</td><td>Claude Pricing</td><td>2026-08-11</td></tr><tr><td>新用户或学生福利</td><td>Education 面向高校机构，非个人通用</td><td>Anthropic 官方公告</td><td>2026-08-11</td></tr><tr><td>API 或 BYOK</td><td>API 按 Token 计费；桌面端不支持 BYOK</td><td>Claude Pricing</td><td>2026-08-11</td></tr></tbody></table><p><strong>重要提示</strong>：面向中国大陆新手时，应把地区可用性、注册与支付条件、账号风控、申诉渠道和订阅中断损失列在功能介绍之前。作者当前账号被封，订阅可能随时中断，教程不把订阅价格作为推荐的唯一依据。</p><h2 id="_5-核心能力" tabindex="-1">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><p>官方定位的综合能力（工作事务、内容、设计、代码、完整交付物）来自官方说明，<strong>本轮均未实测</strong>。官方功能说明与作者实际测试分开记录：官方 Pro 页面明确包含 Claude Code、Claude Cowork、Claude Design 和 Claude Science；具体桌面任务体验待账号可用后验证。</p><h2 id="_6-界面与工作方式" tabindex="-1">6. 界面与工作方式 <a class="header-anchor" href="#_6-界面与工作方式" aria-label="Permalink to &quot;6. 界面与工作方式&quot;">​</a></h2><ul><li>运行位置：Windows/macOS 官方桌面应用（云端处理）；</li><li>用户如何观察和控制执行过程：登录前仅有欢迎页；登录后的导航、任务过程、权限提示、产物定位待补截图与实测。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>观察记录</th><th>适用前提</th></tr></thead><tbody><tr><td>新手上手难度</td><td>欢迎页极简，注册登录后未验证</td><td>需稳定账号</td></tr><tr><td>账号与地区可用性</td><td><strong>前置风险点</strong>：作者账号被封，申诉结果未记录</td><td>地区与风控政策</td></tr><tr><td>图形界面清晰度</td><td>登录前界面简洁；主界面未验证</td><td>待复测</td></tr><tr><td>任务状态反馈</td><td>未验证</td><td>待复测</td></tr><tr><td>权限提示与确认</td><td>未验证</td><td>待复测</td></tr><tr><td>上下文处理</td><td>未验证</td><td>待复测</td></tr><tr><td>过程可控性</td><td>未验证</td><td>待复测</td></tr><tr><td>结果定位与验证</td><td>未验证</td><td>待复测</td></tr><tr><td>生态与扩展</td><td>官方 Pro 含 Code/Cowork/Design/Science（官方说明）</td><td>未实测</td></tr></tbody></table><h2 id="_7-三类实测任务" tabindex="-1">7. 三类实测任务 <a class="header-anchor" href="#_7-三类实测任务" aria-label="Permalink to &quot;7. 三类实测任务&quot;">​</a></h2><h3 id="_7-1-共同基准任务" tabindex="-1">7.1 共同基准任务 <a class="header-anchor" href="#_7-1-共同基准任务" aria-label="Permalink to &quot;7.1 共同基准任务&quot;">​</a></h3><p><strong>阻塞</strong>：因账号被封无法执行。按教程约定，此阻塞不能由网页聊天或第三方通道替代桌面官方体验，故不补跑、不补数据。</p><h3 id="_7-2-优势任务" tabindex="-1">7.2 优势任务 <a class="header-anchor" href="#_7-2-优势任务" aria-label="Permalink to &quot;7.2 优势任务&quot;">​</a></h3><p>候选：把零散资料整理成完整教程文档或网页交付物。待账号可用后补测。</p><h3 id="_7-3-边界任务" tabindex="-1">7.3 边界任务 <a class="header-anchor" href="#_7-3-边界任务" aria-label="Permalink to &quot;7.3 边界任务&quot;">​</a></h3><p>候选：账号无法登录、服务地区受限或任务需要不可用工具时，记录中断点、数据损失和申诉路径。作者封号经历本身即是一条真实的账号可用性边界案例。</p><h2 id="_8-遇到的问题与恢复" tabindex="-1">8. 遇到的问题与恢复 <a class="header-anchor" href="#_8-遇到的问题与恢复" aria-label="Permalink to &quot;8. 遇到的问题与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现条件</th><th>对结果的影响</th><th>恢复步骤</th><th>新手能否独立处理</th></tr></thead><tbody><tr><td>账号被封</td><td>作者亲历；具体触发原因未核实</td><td>桌面端与订阅全部不可用，共同任务阻塞</td><td>走官方申诉渠道；结果待记录</td><td>未知；需依赖官方申诉流程</td></tr></tbody></table><p>写作纪律：不猜测封号原因，不把单个封号经历写成普遍封号率，不提供绕过地区限制或平台风控的方法。同时记录喜欢的设计：欢迎页品牌呈现干净、无干扰信息，适合新手建立第一印象——但这不构成功能评价。</p><h2 id="_9-适合与不适合" tabindex="-1">9. 适合与不适合 <a class="header-anchor" href="#_9-适合与不适合" aria-label="Permalink to &quot;9. 适合与不适合&quot;">​</a></h2><h3 id="更适合" tabindex="-1">更适合 <a class="header-anchor" href="#更适合" aria-label="Permalink to &quot;更适合&quot;">​</a></h3><ul><li>官方服务覆盖、账号与支付条件稳定的读者；</li><li>需要综合能力（工作+内容+设计+代码）且愿意接受云端处理资料的用户。</li></ul><h3 id="可能不适合" tabindex="-1">可能不适合 <a class="header-anchor" href="#可能不适合" aria-label="Permalink to &quot;可能不适合&quot;">​</a></h3><ul><li>无法稳定注册、登录、付费的用户；</li><li>承担不起账号中断损失的读者（订阅中断意味着能力与历史记录同时不可用）；</li><li>希望「先安装就能用」的零基础新手——账号风险会让首次体验无法预期。</li></ul><h2 id="_10-最终结论" tabindex="-1">10. 最终结论 <a class="header-anchor" href="#_10-最终结论" aria-label="Permalink to &quot;10. 最终结论&quot;">​</a></h2><ul><li>是否推荐新手试用：<strong>先做账号可用性检查</strong>，账号稳定后再谈试用；</li><li>什么条件下值得购买官方订阅：官方服务覆盖本地区、支付渠道可用、能接受账号中断风险时，可考虑 Pro 起步；Max 档在用量需求确认前不必购买；</li><li>最适合作为主 Agent、辅助 Agent 还是专用工具：潜在主 Agent 候选，但本轮因账号问题无法验证；</li><li>与相邻产品的差异：与 Codex 同为海外综合型，能力维度重叠度高，但账号可用性与支付路径差异明显；本轮两者均无任务实测对照（Codex 已实测、Claude 未实测），不能直接比较任务表现；</li><li>仍需要后续版本继续核验：账号申诉结果、登录后主界面、统一基准任务、Free 档实际额度与用量重置规则。</li></ul><h2 id="附录-a-截图清单" tabindex="-1">附录 A：截图清单 <a class="header-anchor" href="#附录-a-截图清单" aria-label="Permalink to &quot;附录 A：截图清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>截图</th><th>用途</th><th>日期或版本</th><th>是否脱敏</th><th>替代文字</th></tr></thead><tbody><tr><td>无（未进入统一任务）</td><td>仅保存登录前欢迎页与可见受限界面（如有）</td><td>1.22209.3.0</td><td>需遮挡身份信息</td><td>登录前欢迎页</td></tr></tbody></table><h2 id="附录-b-信息来源" tabindex="-1">附录 B：信息来源 <a class="header-anchor" href="#附录-b-信息来源" aria-label="Permalink to &quot;附录 B：信息来源&quot;">​</a></h2><ul><li><a href="https://claude.com/pricing" target="_blank" rel="noreferrer">Claude Pricing</a>（访问日期 2026-08-11）</li><li><a href="https://www.anthropic.com/news/introducing-claude-for-education" target="_blank" rel="noreferrer">Introducing Claude for Education</a>（访问日期 2026-08-11）</li><li>作者账号封禁经历：个人记录，标注为「作者亲历、原因未核实」，不迁移为普遍结论</li></ul><h2 id="附录-c-内容性质标记" tabindex="-1">附录 C：内容性质标记 <a class="header-anchor" href="#附录-c-内容性质标记" aria-label="Permalink to &quot;附录 C：内容性质标记&quot;">​</a></h2><p>本文区分：官方事实（订阅价格、Pro 包含能力，来自官方页面）、作者亲历（账号被封，原因未核实）、实际测试（仅登录前界面核对）、仍待验证的判断（登录后体验、任务表现）。没有绕过限制的内容。</p>',39)])])}const p=a(i,[["render",r]]);export{b as __pageData,p as default};
